def convert(value):
    return value * 60

def read_value():
    while True:
        try:
            text = input("Value or quit: ").strip().lower()
        except EOFError:
            return None
        if text == "quit":
            return None
        try:
            return float(text)
        except ValueError:
            print("Number needed")

def session():
    while True:
        try:
            operation = input("minutes, hours or quit: ").strip().lower()
        except EOFError:
            break
        if operation == "quit":
            break
        if operation != "minutes" and operation != "hours":
            print("Unknown operation")
            continue
        value = read_value()
        if value is None:
            break
        print(convert(value))
    print("Bye")

session()
